CREATE TABLE CORE.T_FACT_CUSTOMER_RETURN_LINE_1 (
   CUST_ORDER_RETURN_SID               NUMERIC         NOT NULL COMMENT 'The unique identifier (surrogate key) for return of customer order',
   CUST_ORDER_RETURN_POS_NR            NUMERIC(38,0)   NOT NULL COMMENT 'A number of an particular position ( product ) in an return order',
   WSHOP_CD                            VARCHAR(5)      COMMENT 'The unique code for the Lidl webshop',
   CUST_ORDER_SID                      NUMERIC         COMMENT 'The unique identifier (surrogate key) for customer order',
   CUST_ORDER_POS_NR                   NUMERIC(38,0)   COMMENT 'The particular position number of an item_1 in an order',
   PROD_VARIANT_SID                    NUMERIC         COMMENT 'Returned product',
   CUST_SID                            NUMERIC         COMMENT 'The unique identifier (surrogate key) for the customer',
   CURR_CD                             VARCHAR(5)      COMMENT 'The code identifying the currency according to ISO-4217.',
   CUST_ORDER_TYPE_CD                  VARCHAR(5)      COMMENT 'This field contains codes for different credit notes for returns, for example ZREU for returns in Lidl''s warehouse and ZRET for returns in third party''s warehouse and so on.',
   DELIVERY_ADDR_SID                   NUMERIC         COMMENT 'The unique identifier (sk) for the delivery address_1 where original order was delivered',
   BILLING_ADDR_SID                    NUMERIC         COMMENT 'The unique identifier (sk) for the billing address_1',
   PROD_RETURN_REASON_CD               VARCHAR(5)      COMMENT 'The code for the article return reason on position level  (101, 900, etc)',
   ORDER_RETURN_REASON_CD              VARCHAR(5)      COMMENT 'The code for the reason code on return document level .( 401 - Leeres Paket, 104 - Artikel_1 unvollständig , etc)',
   PROD_SID                            NUMERIC         COMMENT 'The unique identifier (surrogate key) for the product',
   CUST_PAYM_METHOD_CD                 VARCHAR(5)      COMMENT 'Unique code of the payment method',
   RETURN_WH_SID                       NUMERIC         COMMENT 'The unique identifier (surrogate key) for the warehouse handling the return.',
   CUST_ORDER_RETURN_NR                VARCHAR(20)     NOT NULL COMMENT 'An original return order number',
   CUST_ORDER_NR                       VARCHAR(20)     COMMENT 'The original order number of the source system',
   CUST_ORDER_RETURN_CREATE_TMSP       TIMESTAMP_TZ(9) COMMENT 'Creation timestamp of the return. ',
   CUST_ORDER_CREATE_TMSP              TIMESTAMP_TZ(9) COMMENT 'The timestamp when order was created in source system ( is used in reporting)',
   CUST_ORDER_DT                       DATE            COMMENT 'The date when order was made',
   CUST_ORDER_RETURN_DT                DATE            COMMENT 'The date when return was made',
   PROD_QTY                            NUMERIC(38,5)   COMMENT 'Quantity of a particular product returned',
   RETURN_PAYM_TO_CUST_TMSP            TIMESTAMP_LTZ(9) COMMENT 'The timestamp when the payment is transferred to the customer in case of a returned item.',
   PROD_PRICE_NET_LOCAL_VAL            NUMERIC(38,5)   COMMENT 'Original ( listed ) price of a returned product netto in local currency',
   PROD_PRICE_GROSS_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Original ( listed ) price of a  returned product gross in local currency',
   PROD_PRICE_VAT_LOCAL_VAL            NUMERIC(38,5)   COMMENT 'Original ( listed ) vat  on price of a returned  product in local currency',
   PROD_COUPON_NET_LOCAL_VAL           NUMERIC(38,5)   COMMENT 'An amount of discount coupon for a  returned product net in local currency',
   PROD_COUPON_GROSS_LOCAL_VAL         NUMERIC(38,5)   COMMENT 'An amount of discount coupon for a  returned product gross in local currency',
   PROD_COUPON_VAT_LOCAL_VAL           NUMERIC(38,5)   COMMENT 'A vat for amount of discount coupon for a returned product in local currency',
   DELIVERY_COST_NET_LOCAL_VAL         NUMERIC(38,5)   COMMENT 'A returned article specific delivery costs netto in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
   DELIVERY_COST_GROSS_LOCAL_VAL       NUMERIC(38,5)   COMMENT 'A returned article  specific delivery costs gross in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
   DELIVERY_COST_VAT_LOCAL_VAL         NUMERIC(38,5)   COMMENT 'A returned article  specific delivery vat value in local currency. This tax value is optional and mostly article dependent. An example is a fridge which has additional delivery costs for which taxes might have to be paid.',
   DELIVERY_COUPON_NET_LOCAL_VAL       NUMERIC(38,5)   COMMENT 'A discount value netto for  returned article specific delivery costs in local currency.',
   DELIVERY_COUPON_GROSS_LOCAL_VAL     NUMERIC(38,5)   COMMENT 'A discount value gross for  returned article specific delivery costs in local currency.',
   DELIVERY_COUPON_VAT_LOCAL_VAL       NUMERIC(38,5)   COMMENT 'A discount vat value for  returned article specific delivery costs in local currency.',
   DELIVERY_PAUSHAL_GROSS_LOCAL_VAL    NUMERIC(38,5)   COMMENT 'A paushal for delivery costs splitted per every order position in gross and local currency',
   DELIVERY_PAUSHAL_NET_LOCAL_VAL      NUMERIC(38,5)   COMMENT 'A paushal for delivery costs splitted per every order position in netto and local currency',
   DELIVERY_PAUSHAL_VAT_LOCAL_VAL      NUMERIC(38,5)   COMMENT 'The vat value of the paushal delivery costs splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_NET_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Additional net delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency.',
   ADD_DELIVERY_PAUSHAL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Additional gross delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_VAT_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Additional vat on delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_NET_LOCAL_VAL NUMERIC(38,5)   COMMENT 'A discount value netto for paushal delivery cost splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'A discount value gross for paushal delivery cost splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_VAT_LOCAL_VAL NUMERIC(38,5)   COMMENT 'A discount vat value for paushal delivery cost splitted per every order position in local currency',
   IVP_PRICE_NET_LOCAL_VAL             NUMERIC(38,5)   COMMENT 'Internal invoice price in local currency  netto',
   GLD_PRICE_NET_LOCAL_VAL             NUMERIC(38,5)   COMMENT 'Moving average price in local currency netto',
   GLD_UNIT_PRICE_NET_EUR_VAL          NUMERIC(38,5)   COMMENT 'The gld unit_1 price in sales_1 order line in euros for internal margin calculations',
   IVP_ORIGINAL_PRICE_NET_LOCAL_VAL    NUMERIC(38,5)   COMMENT 'Internal invoice price in local currency  netto ( may be null and is used in calculation of ivp_price_net_local_val )',
   IVP_UNIT_PRICE_NET_EUR_VAL          NUMERIC(38,5)   COMMENT 'This field is a derived one based on ivp_original_unit_price_net_eur_val and gld_unit_price_net_eur_val',
   IVP_ORIGINAL_UNIT_PRICE_NET_EUR_VAL NUMERIC(38,5)   COMMENT 'The ivp original unit_1 prices in sales_1 order line in euros for internal margin calculations',
   COGS_PRICE_NET_LOCAL_VAL            NUMERIC(38,5)   COMMENT 'Cost-of-Goods-sold, short: CoGs. Needed for calc of margin (= revenue - cogs )',
   SELLBACK_NET_LOCAL_VAL              NUMERIC(38,5)   COMMENT 'A sellback value net for returned article specific in local currency. Amount which is discounted from the product internal price after it is returned, depending on its condition (whether it is damaged or not). ',
   ADD_SERVICES_VAT_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Additional services vat value of a returned article in local currency. This cost is optional and mostly article dependent.',
   ADD_SERVICES_GROSS_LOCAL_VAL        NUMERIC(38,5)   COMMENT 'Additional services gross value of a returned article in local currency. This cost is optional and mostly article dependent.',
   ADD_SERVICES_NET_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Additional services net value of a returned article in local currency. This cost is optional and mostly article dependent.',
   DROPSHIPMENT_ORDER_FG               BOOLEAN         COMMENT 'In case the material is being sent from the supplier_1 this field will be filled.',
   RETURN_WH_CD                        VARCHAR(5)      COMMENT 'A short  unique code for warehouse handling the return.',
   IS_CREDIT_NOTE_ISSUED_FG            BOOLEAN         COMMENT 'Flag that is set if credit note was isssued for a return',
   IS_LEGACY_FG                        BOOLEAN         COMMENT 'Technical field used to identify legacy data (from Qlik legacy systems vs_1 generic data flows), for further use as a filter condition',
   PROD_NR                             VARCHAR(20)     COMMENT 'The number for internal onlineshop product, which is country_1 independent',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   PROD_CONDITION_CD                   VARCHAR(20)     COMMENT 'The condition code of the product. (01 - can be sold online, 02 - needs to be checked, 03 - for scrapping)',
   COGS_PRICE_NET_EUR_VAL              NUMERIC(38,5)   COMMENT 'Cost of Goods Sold (short: CoGs) in EUR. Calculation of exchange rate is done in SAP.',
   DIST_CHANNEL_CD                     VARCHAR(5)      COMMENT 'The code for the distribution channel ( a channel  through which the goods are sold )',
   DIST_CHANNEL_TYPE_CD                VARCHAR(5)      COMMENT 'A  type of distribution channel ( Wshop for LD Webshop , IC for Intercompany)',
   DIST_COUNTRY_CD                     VARCHAR(5)      COMMENT 'The unique code for a country_1 according to ISO-3166 Alpha-2. E.g. \"DE\" for Germany or \"FR\" for France',
   DIST_ZONE_CD                        VARCHAR(5)      COMMENT 'The unique code for a distribution zone ( f.e. BAL , CAN, etc)',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_FACT_CUSTOMER_RETURN_LINE PRIMARY KEY (CUST_ORDER_RETURN_SID, CUST_ORDER_RETURN_POS_NR) NOT ENFORCED 
)  COMMENT = 'The returns for an  order placed from a customer within the onlineshop to receive the wanted items, which he actually he payed for. Table contain information about details of individual returned items';
